function emitLeadDust(b,c,strong){let count=strong?30:16;for(let k=0;k<count;k++){let tangentX=-c.ny,tangentY=c.nx,dir=k%2?1:-1,speed=35+Math.random()*(strong?140:90),out=10+Math.random()*25;b.special.dust.push({x:c.x,y:c.y,vx:tangentX*dir*speed+c.nx*out,vy:tangentY*dir*speed+c.ny*out,age:0,life:.65+Math.random()*.55,radius:4+Math.random()*7,tone:110+Math.floor(Math.random()*45)})}if(b.special.dust.length>160)b.special.dust.splice(0,b.special.dust.length-160)}
