// Four-neighbour connectivity: only components attached to either side wall remain supported.
function detachLeadIslands(b,board,releaseAnchors=false){let material=b.special.boards[board].material,seen=new Uint8Array(material.length),origin=b.x<330?36:348;for(let first=0;first<material.length;first++){if(!material[first]||seen[first])continue;let cells=[],queue=[first],anchored=false;seen[first]=1;for(let q=0;q<queue.length;q++){let k=queue[q],col=k%138,row=Math.floor(k/138);cells.push(k);if(col===0||col===137)anchored=true;for(const [x,y] of [[col-1,row],[col+1,row],[col,row-1],[col,row+1]]){if(x<0||x>=138||y<0||y>=15)continue;let n=y*138+x;if(material[n]&&!seen[n]){seen[n]=1;queue.push(n)}}}if(anchored&&!releaseAnchors)continue;let cx=cells.reduce((v,k)=>v+k%138*2+1,0)/cells.length,cy=cells.reduce((v,k)=>v+Math.floor(k/138)*2+1,0)/cells.length;let points=cells.map(k=>({x:k%138*2+1-cx,y:Math.floor(k/138)*2+1-cy}));cells.forEach(k=>material[k]=0);b.special.debris.push({x:origin+cx,y:258+board*113.2+cy,vx:0,vy:0,angle:0,spin:0,generation:0,breakCooldown:.2,inertia:points.reduce((sum,p)=>sum+p.x*p.x+p.y*p.y+2/3,0)/points.length,points,boardIndex:board,color:themePalettes[visualTheme].boards[board],age:0});}}
function tickLeadDebris(b,dt){let list=b.special.debris;for(const d of list){prepareDebris(d);let nearby=Math.abs(b.x-d.x)<d.radius+36&&Math.abs(b.y-d.y)<d.radius+36;let revision=b.special.materialRevision||0;if(d.sleeping&&!nearby&&d.supportRevision===revision)continue;if(d.sleeping){d.sleeping=false;d.restTime=0}d.breakCooldown=Math.max(0,(d.breakCooldown||0)-dt);d.age+=dt;d.vy+=cfg.gravity*dt;d.x+=d.vx*dt;d.y+=d.vy*dt;d.angle+=d.spin*dt;let c=Math.cos(d.angle),s=Math.sin(d.angle),nearest=null;if(nearby)for(const p of d.boundary){let x=d.x+p.x*c-p.y*s,y=d.y+p.x*s+p.y*c,dx=x-b.x,dy=y-b.y,dist=Math.hypot(dx,dy);if(dist<34&&(!nearest||dist<nearest.dist))nearest={dx,dy,dist,x,y};}if(nearest){let n=nearest,dist=Math.max(.01,n.dist),nx=n.dx/dist,ny=n.dy/dist;if(n.dist<.01){nx=0;ny=1}let overlap=34-n.dist;d.x+=nx*overlap;d.y+=ny*overlap;let closing=(b.vx-d.vx)*nx+(b.v-d.vy)*ny;if(closing>cfg.debrisBreakSpeed)requestDebrisBreak(d,n.x,n.y,closing);if(closing>0){d.vx+=nx*closing*1.15;d.vy+=ny*closing*1.15;let torque=(n.x-d.x)*ny-(n.y-d.y)*nx;d.spin=Math.max(-10,Math.min(10,d.spin+torque*closing/Math.max(100,d.points.length*12)))}}let origin=b.x<330?36:348;let cos=Math.cos(d.angle),sin=Math.sin(d.angle),minX=Infinity,maxX=-Infinity,maxY=-Infinity;for(const p of d.boundary){let px=d.x+p.x*cos-p.y*sin,py=d.y+p.x*sin+p.y*cos;minX=Math.min(minX,px-1);maxX=Math.max(maxX,px+1);maxY=Math.max(maxY,py+1)}if(minX<origin){d.x+=origin-minX;d.vx=Math.abs(d.vx)*.15}if(maxX>origin+276){d.x-=maxX-origin-276;d.vx=-Math.abs(d.vx)*.15}let lift=Math.max(0,maxY-1140),supportPoints=[];if(maxY>=1140-.5){for(const p of d.boundary){let px=d.x+p.x*cos-p.y*sin,py=d.y+p.x*sin+p.y*cos+1;if(py>=maxY-1.5)supportPoints.push(px)}}if(d.vy>=0){for(const p of d.boundary){let px=d.x+p.x*cos-p.y*sin,py=d.y+p.x*sin+p.y*cos+1,prevY=py-d.vy*dt;let col=Math.max(0,Math.min(137,Math.floor((px-origin)/2)));if(px<origin||px>origin+276)continue;for(let j=Math.max(0,Math.ceil((prevY-288-1)/113.2));j<=Math.min(7,Math.floor((py-258)/113.2));j++){let top=258+j*113.2;if(py<top||prevY>top+30+1)continue;let material=b.special.boards[j].material;for(let row=0;row<15;row++){if(!material[row*138+col])continue;let surface=top+row*2;if(prevY<=surface+1&&py>=surface){lift=Math.max(lift,py-surface);supportPoints.push(px);break}}}}}if(lift>0){if(d.vy>cfg.debrisBreakSpeed)requestDebrisBreak(d,d.x,maxY,d.vy);d.y-=lift;d.vy=0;d.vx*=Math.exp(-9*dt);if(supportPoints.length){let left=Math.min(...supportPoints),right=Math.max(...supportPoints),pivot=d.x<left?left:d.x>right?right:null;if(pivot!==null){let lever=d.x-pivot;let vertical=maxY-d.y;let inertia=(d.inertia||1)+lever*lever+vertical*vertical;let torque=cfg.gravity*lever;d.spin+=torque/Math.max(1,inertia)*dt;let turn=d.spin*dt;let c=Math.cos(turn),s=Math.sin(turn),rx=d.x-pivot,ry=-vertical;d.x=pivot+rx*c-ry*s;d.y=maxY+rx*s+ry*c;}else d.spin*=Math.exp(-14*dt)}else d.spin*=Math.exp(-14*dt)}d.vx*=Math.exp(-.25*dt);d.spin*=Math.exp(-.2*dt);if(lift>0&&Math.abs(d.vx)<1&&Math.abs(d.vy)<1&&Math.abs(d.spin)<.025&&!d.breakRequest){d.restTime=(d.restTime||0)+dt;if(d.restTime>.5){d.sleeping=true;d.vx=0;d.vy=0;d.spin=0;d.supportRevision=revision}}else d.restTime=0;}splitLeadDebris(b);}
function drawLeadDebris(b){ctx.save();let origin=b.x<330?36:348;ctx.beginPath();ctx.rect(origin,76,276,1081);ctx.clip();for(const d of b.special.debris){ctx.save();ctx.translate(d.x,d.y);ctx.rotate(d.angle);prepareDebris(d);ctx.fillStyle=Number.isInteger(d.boardIndex)?themePalettes[visualTheme].boards[d.boardIndex]:d.color;if(d.cachedPath)ctx.fill(d.cachedPath);else{ctx.beginPath();for(const r of d.runs)ctx.rect(r.x,r.y,r.w,2.05);ctx.fill()}ctx.restore()}ctx.restore();}

function requestDebrisBreak(d,x,y,speed){if(d.points.length<cfg.debrisBreakSize||(d.generation||0)>=cfg.debrisBreakDepth||d.breakCooldown>0)return;if(!d.breakRequest||speed>d.breakRequest.speed)d.breakRequest={x,y,speed};}
function splitLeadDebris(b){let result=[];for(const d of b.special.debris){if(!d.breakRequest){result.push(d);continue}let hit=d.breakRequest;delete d.breakRequest;let c=Math.cos(d.angle),s=Math.sin(d.angle),hx=(hit.x-d.x)*c+(hit.y-d.y)*s,hy=-(hit.x-d.x)*s+(hit.y-d.y)*c;let angle=Math.atan2(-hy,-hx)+Math.PI/2+(Math.random()-.5)*.5,nx=Math.cos(angle),ny=Math.sin(angle);let values=d.points.map(p=>p.x*nx+p.y*ny).sort((a,b)=>a-b),threshold=values[Math.floor(values.length*.5)];let groups=[[],[]];d.points.forEach(p=>groups[p.x*nx+p.y*ny<threshold?0:1].push(p));if(groups.some(g=>g.length<8)){result.push(d);continue}for(let i=0;i<2;i++){let points=groups[i],cx=points.reduce((v,p)=>v+p.x,0)/points.length,cy=points.reduce((v,p)=>v+p.y,0)/points.length,rx=cx*c-cy*s,ry=cx*s+cy*c;let centered=points.map(p=>({x:p.x-cx,y:p.y-cy}));let separation=(i?1:-1)*Math.min(70,hit.speed*.12);result.push({...d,x:d.x+rx,y:d.y+ry,vx:d.vx-d.spin*ry+nx*separation,vy:d.vy+d.spin*rx+ny*separation,spin:d.spin+(i?1:-1)*1.5,points:centered,inertia:centered.reduce((v,p)=>v+p.x*p.x+p.y*p.y+2/3,0)/centered.length,generation:(d.generation||0)+1,breakCooldown:.25})}}b.special.debris=result;}

// Immutable shape metadata is rebuilt only when a fragment receives new material points.
function prepareDebris(d){if(d.shapeSource===d.points)return;d.shapeSource=d.points;d.sleeping=false;d.restTime=0;let minX=Infinity,minY=Infinity;for(const p of d.points){minX=Math.min(minX,p.x);minY=Math.min(minY,p.y)}let cells=new Map(),rows=new Map();d.radius=0;for(const p of d.points){let x=Math.round((p.x-minX)/2),y=Math.round((p.y-minY)/2);cells.set(x+','+y,p);if(!rows.has(y))rows.set(y,[]);rows.get(y).push(x);d.radius=Math.max(d.radius,Math.hypot(p.x,p.y)+2)}d.boundary=[];for(const [key,p] of cells){let [x,y]=key.split(',').map(Number);if(!cells.has((x-1)+','+y)||!cells.has((x+1)+','+y)||!cells.has(x+','+(y-1))||!cells.has(x+','+(y+1)))d.boundary.push(p)}d.runs=[];for(const [y,xs] of rows){xs.sort((a,b)=>a-b);let start=xs[0],last=start;for(let i=1;i<=xs.length;i++){if(i<xs.length&&xs[i]===last+1){last=xs[i];continue}d.runs.push({x:minX+start*2-1,y:minY+y*2-1,w:(last-start+1)*2+.05});start=last=xs[i]}}d.cachedPath=typeof Path2D!=='undefined'?new Path2D():null;if(d.cachedPath)for(const r of d.runs)d.cachedPath.rect(r.x,r.y,r.w,2.05);}

function tickMagneticField(b,dt){let f=b.special.magnetField;if(!f)return;f.remaining-=dt;if(f.remaining<=0){b.special.magnetField=null;return}if(b.action||b.special.arena||!f.source||f.source.done)return;let targetCenter=b.x<330?174:486,sourceCenter=f.source.x<330?174:486;let anchorX=targetCenter+(f.source.x-sourceCenter)*.65,anchorY=f.source.y;let dx=anchorX-b.x,dy=anchorY-b.y,distance=Math.hypot(dx,dy),force=cfg.magnetPull*(f.ultimate?1.35:1),falloff=Math.min(1,distance/55);let ax=distance>1?dx/distance*force*falloff:0,ay=distance>1?dy/distance*force*falloff:0;let damp=Math.exp(-cfg.magnetDamping*dt);b.vx=Math.max(-260,Math.min(260,(b.vx+ax*dt)*damp));b.v=Math.max(-600,Math.min(600,(b.v+ay*dt)*damp));}
function drawMagneticField(b){let s=b.special;ctx.save();if(b.role==='magnet'){ctx.fillStyle='#0a071ac9';ctx.beginPath();ctx.arc(b.x,b.y,36,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#c8a7f0';ctx.lineWidth=2;for(let k=0;k<3;k++){ctx.beginPath();ctx.ellipse(b.x,b.y,42+k*5,14+k*4,time*2+k,0,Math.PI*2);ctx.stroke()}ctx.strokeStyle='#eaa2c4';ctx.lineWidth=3;ctx.beginPath();ctx.arc(b.x,b.y,38,-Math.PI/2,-Math.PI/2+Math.PI*2*s.magnetEnergy/100);ctx.stroke()}let f=s.magnetField;if(f){ctx.strokeStyle=f.ultimate?'#f3b2df':'#9ebffc';ctx.lineWidth=1.5;ctx.globalAlpha=.65;for(let k=0;k<2;k++){ctx.beginPath();ctx.ellipse(b.x,b.y,40+k*6,17+k*3,time*2+k,0,Math.PI*2);ctx.stroke()}ctx.font='bold 13px system-ui';ctx.textAlign='center';ctx.fillStyle=ctx.strokeStyle;ctx.fillText(f.ultimate?'± 强磁场':'±',b.x,b.y-47);if(f.source){ctx.globalAlpha=.65;ctx.lineWidth=f.ultimate?3:2;ctx.setLineDash([8,4]);ctx.beginPath();ctx.moveTo(f.source.x,f.source.y);ctx.quadraticCurveTo(330,Math.min(f.source.y,b.y)-45,b.x,b.y);ctx.stroke()}}ctx.restore();}

function drawShockState(b){let s=b.special;ctx.save();if(s.resonanceNotice>0){ctx.globalAlpha=Math.min(1,s.resonanceNotice/.25);ctx.fillStyle='#ffe8a6';ctx.font='bold 18px system-ui';ctx.textAlign='center';ctx.shadowColor='#7e4f12';ctx.shadowBlur=8;ctx.fillText('共振！',b.x,b.y-60-(.9-s.resonanceNotice)*15);ctx.globalAlpha=1;ctx.shadowBlur=0}if(s.stunTime>0){ctx.fillStyle='#ffeeb1';ctx.font='bold 17px system-ui';ctx.textAlign='center';for(let k=0;k<3;k++){let a=time*5+k*Math.PI*2/3;ctx.fillText('✦',b.x+Math.cos(a)*25,b.y-43+Math.sin(a)*5)}ctx.font='12px system-ui';ctx.fillText('昏迷',b.x,b.y-60)}ctx.restore();}

function resonanceProperties(j){let strength=Math.log10(1+levels[j]);return {omega:Math.PI*2*(cfg.resFrequency+.18*(j%3)+.12*strength),damping:cfg.resDamping*(1+.12*(j%4)),limit:cfg.resLimit*(1+.14*strength)}}
function tickResonance(b,dt){if(b.role!=='gyro')return;b.special.resonanceNotice=Math.max(0,b.special.resonanceNotice-dt);b.special.resCooldown=Math.max(0,b.special.resCooldown-dt);b.special.boards.forEach((p,j)=>{let r=p.resonance,properties=resonanceProperties(j);let steps=Math.max(1,Math.ceil(dt/.004)),h=dt/steps;for(let i=0;i<steps;i++){r.velocity+=(-(properties.omega**2)*r.position-properties.damping*2*r.velocity)*h;r.position+=r.velocity*h}r.flash=Math.max(0,r.flash-dt);let amplitude=Math.hypot(r.position,r.velocity/properties.omega)/properties.limit;r.crackClock+=dt;if(amplitude>.12&&r.crackClock>=.065){r.crackClock=0;let stress=Math.min(1,amplitude+r.fatigue);if(r.cracks.length<Math.floor(stress*12)){let x=20+Math.random()*236;r.cracks.push({points:[{x,y:15}],direction:Math.random()<.5?-1:1})}for(const crack of r.cracks){let last=crack.points.at(-1);if(last.x<=2||last.x>=274||crack.points.length>=40)continue;let wave=Math.sin(last.x/276*Math.PI*3+time*properties.omega);crack.points.push({x:Math.max(2,Math.min(274,last.x+crack.direction*(1+stress*3))),y:Math.max(2,Math.min(28,last.y+wave*2.2+(Math.random()-.5)*1.5))})}}})}
function drawResonance(b,j,x,y){if(b.role!=='gyro')return;let r=b.special.boards[j].resonance;ctx.save();let fatigue=Math.min(1,r.fatigue);if(fatigue>.015){ctx.save();ctx.beginPath();ctx.roundRect(x+1,y+1,274,28,4);ctx.clip();ctx.fillStyle='rgba(231,244,246,'+(fatigue*.17)+')';ctx.fillRect(x,y,276,30);let seed=(j+1)*731;const random=()=>{seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296};for(let k=0;k<Math.floor(fatigue*100);k++){let px=x+8+random()*260,py=y+4+random()*22,len=2+random()*10;ctx.strokeStyle='rgba(244,251,250,'+(.05+fatigue*.24)+')';ctx.lineWidth=.5+random()*.8;ctx.beginPath();ctx.moveTo(px,py);ctx.lineTo(px+len,py+Math.sin(px*.09)*2);ctx.stroke()}for(const crack of r.cracks){if(crack.points.length<2)continue;ctx.beginPath();crack.points.forEach((p,k)=>k?ctx.lineTo(x+p.x,y+p.y):ctx.moveTo(x+p.x,y+p.y));ctx.strokeStyle='rgba(227,245,248,'+(fatigue*.24)+')';ctx.lineWidth=3+fatigue*5;ctx.stroke()}ctx.restore()}let stress=Math.min(1,Math.hypot(r.position,r.velocity/resonanceProperties(j).omega)/resonanceProperties(j).limit+r.fatigue);ctx.strokeStyle=r.flash>.15?'#ffe2a0':'#d5bd7866';ctx.lineWidth=1.5;ctx.beginPath();for(let k=0;k<=30;k++){let px=x+k*9.2,py=y+15+Math.sin(k*.85+time*12)*stress*5;k?ctx.lineTo(px,py):ctx.moveTo(px,py)}ctx.stroke();ctx.strokeStyle='#f0fcff';ctx.lineWidth=.7+fatigue*.8;ctx.globalAlpha=.25+Math.min(1,stress)*.65;for(const crack of r.cracks){ctx.beginPath();crack.points.forEach((p,k)=>k?ctx.lineTo(x+p.x,y+p.y):ctx.moveTo(x+p.x,y+p.y));ctx.stroke()}ctx.restore()}

function tickBending(b,dt){let ratio=1;for(let j=0;j<b.special.boards.length;j++){let m=b.special.boards[j].bend;tickMagnetRift(m,dt);m.pulse=Math.max(0,m.pulse-dt);for(let step=0,n=Math.max(1,Math.ceil(dt/.003));step<n;step++){let h=dt/n;for(let k=1;k<24;k++){let node=m.nodes[k],left=m.nodes[k-1],right=m.nodes[k+1];let force=(m.pulse>0?node.load*m.polarity*cfg.bendForce*ratio:0);let rift=magnetRiftLoad(m,k);node.pull=(node.pull||0)*Math.exp(-h*3)+rift*cfg.magnetRiftForce*h;force+=rift*cfg.bendForce*.55;let stiffness=1+.1*Math.log10(1+levels[j]);let neighbour=0;if(m.links[k-1]<cfg.bendTear)neighbour+=left.y-node.y;if(m.links[k]<cfg.bendTear)neighbour+=right.y-node.y;node.v+=(force-neighbour*-110*stiffness-(node.y-node.rest)*40*stiffness-node.v*8)*h;node.y=Math.max(-55,Math.min(55,node.y+node.v*h));let strain=node.y-node.rest;if(Math.abs(strain)>cfg.bendElastic*cfg.bendResistance)node.rest+=Math.sign(strain)*(Math.abs(strain)-cfg.bendElastic*cfg.bendResistance)*h*2;node.load*=Math.exp(-h*.3)}for(let k=0;k<24;k++){if(!m.present[k])continue;let a=m.nodes[k],z=m.nodes[k+1],strain=Math.hypot(z.y-a.y,(z.pull||0)-(a.pull||0));if(strain>cfg.bendElastic*.18)m.links[k]+=h*(strain-cfg.bendElastic*.18)*.4/(stiffnessForBend(j)*cfg.bendResistance)}}let first=0;while(first<24){if(!m.present[first]){first++;continue}let last=first;while(last<23&&m.present[last+1]&&m.links[last]<cfg.bendTear)last++;let anchored=first===0||last===23;if(!anchored){let cx=(first+last+1)*5.75,cy=0,vy=0;for(let k=first;k<=last;k++){cy+=(m.nodes[k].y+m.nodes[k+1].y)/2+15;vy+=(m.nodes[k].v+m.nodes[k+1].v)/2}let count=last-first+1;cy/=count;vy/=count;let segments=[];for(let k=first;k<=last;k++){m.present[k]=false;segments.push({k,x:k*11.5-cx,a:m.nodes[k].y-cy,z:m.nodes[k+1].y-cy})}let width=count*11.5,spin=(m.nodes[last+1].v-m.nodes[first].v)/Math.max(11.5,width);let lateral=0;for(let k=first;k<=last+1;k++)lateral+=m.nodes[k].pull||0;lateral/=(count+1);m.drop.push({x:cx,y:cy,vx:m.polarity*8+lateral*4,vy,angle:0,spin:Math.max(-4,Math.min(4,spin)),segments});}first=last+1}for(let p of m.drop){let previousY=p.y;p.vy+=cfg.gravity*dt;p.x+=p.vx*dt;p.y+=p.vy*dt;p.angle+=p.spin*dt;let c=Math.cos(p.angle),sn=Math.sin(p.angle),base=258+j*113.2,lift=0;let samples=[];for(const segment of p.segments)for(const [x,y] of [[segment.x,segment.a+30],[segment.x+11.5,segment.z+30]])samples.push({x:p.x+x*c-y*sn,y:p.y+x*sn+y*c});for(const point of samples){lift=Math.max(lift,base+point.y-1140);if(p.vy<0)continue;for(let next=j+1;next<b.special.boards.length;next++){let other=b.special.boards[next].bend,col=Math.floor(point.x/11.5);if(col<0||col>23||!other.present[col])continue;let surface=(next-j)*113.2+(other.nodes[col].y+other.nodes[col+1].y)/2,previous=point.y-(p.y-previousY);if(previous<=surface+2&&point.y>=surface)lift=Math.max(lift,point.y-surface)}}if(lift>0){p.y-=lift;p.vy=0;p.vx*=Math.exp(-8*dt);p.spin*=Math.exp(-12*dt)}if(p.x<0||p.x>276){p.x=Math.max(0,Math.min(276,p.x));p.vx*=-.2}}}}
function stiffnessForBend(j){return 1+.1*Math.log10(1+levels[j])}
function bendPassage(b){let m=b.special.boards[b.index].bend,local=b.x-(b.x<330?36:348);for(let k=Math.max(0,Math.floor((local-32)/11.5));k<=Math.min(23,Math.floor((local+32)/11.5));k++)if(m.present[k])return false;return true}
function drawBending(b,j,x,y){let m=b.special.boards[j].bend;ctx.save();let texture=bendBoardTexture(b,j);for(let k=0;k<24;k++){if(!m.present[k])continue;let a=m.nodes[k],z=m.nodes[k+1],slope=(z.y-a.y)/11.5;if(m.pulse>0&&a.load>.15){ctx.save();ctx.globalAlpha=Math.min(.55,a.load*m.pulse/cfg.bendDuration);ctx.strokeStyle=m.polarity>0?'#f0a4c5':'#9ed5ff';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(x+k*11.5,y+a.y+15);ctx.quadraticCurveTo(x+k*11.5-7,y+a.y+m.polarity*28,x+k*11.5,y+a.y+m.polarity*44);ctx.stroke();ctx.restore()}ctx.save();ctx.translate(x+k*11.5,y+a.y);ctx.transform(1,slope,0,1,0,0);ctx.drawImage(texture,k*11.5,0,11.5,30,0,0,11.5,30);ctx.restore();if(m.links[k]>.2){ctx.strokeStyle='#f3e4f3';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(x+(k+.5)*11.5,y+a.y);ctx.lineTo(x+(k+.6)*11.5,y+a.y+15);ctx.lineTo(x+(k+.4)*11.5,y+a.y+30);ctx.stroke()}}drawMagnetRift(b,m,x,y);for(const p of m.drop){ctx.save();ctx.translate(x+p.x,y+p.y);ctx.rotate(p.angle);for(const segment of p.segments){ctx.save();ctx.translate(segment.x,segment.a);ctx.transform(1,(segment.z-segment.a)/11.5,0,1,0,0);ctx.drawImage(texture,segment.k*11.5,0,11.5,30,0,0,11.5,30);ctx.restore()}ctx.restore()}drawGravityRepair(b,b.special.boards[j],x,y);ctx.restore();}
