let top=previous.y<current.y?previous:current,bottom=previous.y<current.y?current:previous;
let upperContact=previous.y<current.y?old:{x,normalY},lowerContact=previous.y<current.y?{x,normalY}:old;
if(upperContact.normalY<.2||lowerContact.normalY>-.2)return;
let origin=b.x<330?36:348,center=Math.max(50,Math.min(226,(old.x+x)/2-origin)),k=Math.floor(center/11.5);
