// Only the nearest surviving plates around the ball may connect.
let upperY=bridgeSurface(top,center,true),lowerY=bridgeSurface(bottom,center);
if(lowerY<=upperY||magnetTargets(b).some(t=>t.state!==top.state&&t.state!==bottom.state&&t.state.bend.present[k]&&bridgeSurface(t,center)>upperY&&bridgeSurface(t,center)<lowerY))return;
