for(const [plate,direction] of [[geometry.top.state.bend,-1],[geometry.bottom.state.bend,1]]){plate.polarity=direction;plate.pulse=Math.max(plate.pulse,.15);for(let n=1;n<24;n++){let distance=Math.abs(n*11.5-m.center);plate.nodes[n].load=Math.max(plate.nodes[n].load,Math.max(0,1-distance/cfg.bendWidth)*cfg.bridgeForce)}}
