if(returning){beginPhaseRecall(b,t,combined,strike?.speed);continue}
b.x+=c.nx*Math.max(0,32.1-c.dist);b.y+=c.ny*Math.max(0,32.1-c.dist);let vx=b.vx-2*c.dot*c.nx,vy=b.v-2*c.dot*c.ny,speed=cfg.bounce+Math.random()*cfg.bounceRandom,scale=speed/Math.max(1,Math.hypot(vx,vy));b.vx=vx*scale;b.v=vy*scale;
